const payload = items[0].json;
const event = $json["X-GitHub-Event"] || payload.headers?.['x-github-event'];
const action = payload.body?.action;

// Only process pull_request events with relevant actions
if (event !== 'pull_request') {
  return [{ json: { skip: true, reason: `Not a pull_request event: ${event}` } }];
}

const relevantActions = ['opened', 'synchronize', 'reopened', 'ready_for_review'];
if (!relevantActions.includes(action)) {
  return [{ json: { skip: true, reason: `Action not relevant: ${action}` } }];
}

// Extract key information
const repo = payload.body.repository;
const pr = payload.body.pull_request;
const installation = payload.body.installation;

return [{
  json: {
    event: 'pull_request',
    action: action,
    repository: {
      id: repo.id,
      name: repo.name,
      full_name: repo.full_name,
      html_url: repo.html_url,
      clone_url: repo.clone_url,
      default_branch: repo.default_branch,
      owner_login: repo.owner.login,
      installation_id: installation?.id
    },
    pull_request: {
      number: pr.number,
      title: pr.title,
      body: pr.body,
      head_sha: pr.head.sha,
      base_sha: pr.base.sha,
      head_ref: pr.head.ref,
      base_ref: pr.base.ref,
      html_url: pr.html_url,
      user: pr.user.login
    },
    timestamp: new Date().toISOString()
  }
}];

const response = items[0].json;

if (response.status === 'queued') {
  return [{
    json: {
      success: true,
      analysis_id: response.analysis_id,
      message: `Analysis queued for PR #${$json.pull_request.number} in ${$json.repository.full_name}`
    }
  }];
}

return [{
  json: {
    success: false,
    error: response.detail || 'Failed to queue analysis'
  }
}];

const pr = $json.pull_request;
const repo = $json.repository;

const message = `✅ *Analysis Queued*\n` +
  `Repository: ${repo.full_name}\n` +
  `PR: #${pr.number} - ${pr.title}\n` +
  `Author: @${pr.user}\n` +
  `Analysis ID: ${$json.analysis_id}\n` +
  `Triggered: ${new Date().toLocaleString()}`;

return [{ json: { text: message, channel: '#code-reviews' } }];

const error = $json.error || 'Unknown error';
const pr = $json.pull_request;
const repo = $json.repository;

const message = `❌ *Analysis Failed to Queue*\n` +
  `Repository: ${repo.full_name}\n` +
  `PR: #${pr.number} - ${pr.title}\n` +
  `Error: ${error}\n` +
  `Time: ${new Date().toLocaleString()}`;

return [{ json: { text: message, channel: '#code-reviews-alerts' } }];

const pr = $json.pull_request;
const repo = $json.repository;

const message = `🔍 *Code Analysis Started*\n` +
  `📦 *Repository:* [${repo.full_name}](${repo.html_url})\n` +
  `🔀 *PR:* [#${pr.number}](${pr.html_url}) - ${pr.title}\n` +
  `👤 *Author:* @${pr.user}\n` +
  `⏰ *Started:* ${new Date().toLocaleString()}\n` +
  `🆔 *Analysis ID:* \`${$json.analysis_id}\``;

return [{ json: { content: message } }];

const analysisId = $json.analysis_id;
// Poll for analysis completion
// In production, use a wait node or separate workflow triggered by analysis completion webhook
return [{ json: { analysis_id: analysisId, poll: true } }];

const analysis = items[0].json;
const repo = $json.repository;
const pr = $json.pull_request;

const emoji = analysis.critical_findings > 0 ? '🚨' : 
              analysis.high_findings > 0 ? '⚠️' : 
              analysis.medium_findings > 0 ? '⚡' : '✅';

let message = `${emoji} *Analysis Complete*\n`;
message += `📦 *Repository:* [${repo.full_name}](${repo.html_url})\n`;
message += `🔀 *PR:* [#${pr.number}](${pr.html_url}) - ${pr.title}\n`;
message += `📊 *Findings:* `;
if (analysis.critical_findings > 0) message += `🔴 ${analysis.critical_findings} Critical `;
if (analysis.high_findings > 0) message += `🟠 ${analysis.high_findings} High `;
if (analysis.medium_findings > 0) message += `🟡 ${analysis.medium_findings} Medium `;
if (analysis.low_findings > 0) message += `🔵 ${analysis.low_findings} Low `;
if (analysis.info_findings > 0) message += `⚪ ${analysis.info_findings} Info `;
message += `\n`;
message += `📈 *Technical Debt:* ${analysis.technical_debt_score?.toFixed(1) || 'N/A'}/100\n`;
message += `🛡️ *Maintainability:* ${analysis.maintainability_index?.toFixed(1) || 'N/A'}/100\n`;
message += `🔗 *View Details:* ${analysis.id}\n`;
message += `⏰ *Completed:* ${new Date().toLocaleString()}`;

return [{ json: { text: message, channel: '#code-reviews' } }];

const analysis = items[0].json;
const repo = $json.repository;
const pr = $json.pull_request;

const color = analysis.critical_findings > 0 ? 0xFF0000 : 
              analysis.high_findings > 0 ? 0xFF8C00 : 
              analysis.medium_findings > 0 ? 0xFFD700 : 0x00FF00;

const embed = {
  title: `Analysis Complete: ${repo.full_name} - PR #${pr.number}`,
  url: pr.html_url,
  color: color,
  fields: [
    { name: '🔴 Critical', value: analysis.critical_findings.toString(), inline: true },
    { name: '🟠 High', value: analysis.high_findings.toString(), inline: true },
    { name: '🟡 Medium', value: analysis.medium_findings.toString(), inline: true },
    { name: '🔵 Low', value: analysis.low_findings.toString(), inline: true },
    { name: '⚪ Info', value: analysis.info_findings.toString(), inline: true },
    { name: '📈 Technical Debt', value: `${analysis.technical_debt_score?.toFixed(1) || 'N/A'}/100`, inline: true },
    { name: '🛡️ Maintainability', value: `${analysis.maintainability_index?.toFixed(1) || 'N/A'}/100`, inline: true },
    { name: '🔀 PR', value: `[#${pr.number}](${pr.html_url})`, inline: true }
  ],
  footer: { text: `Agent Reviewer • Analysis ${analysis.id}` },
  timestamp: new Date().toISOString()
};

return [{ json: { embeds: [embed] } }];

const analysis = items[0].json;
// If there are critical/high findings, post a comment on the PR
if (analysis.critical_findings > 0 || analysis.high_findings > 0) {
  return [{
    json: {
      post_comment: true,
      analysis_id: analysis.id,
      pr_number: $json.pull_request.number,
      repo_full_name: $json.repository.full_name,
      installation_id: $json.repository.installation_id
    }
  }];
}
return [{ json: { post_comment: false } }];

const analysis = $json.analysis_id;
const prNumber = $json.pr_number;
const repo = $json.repo_full_name;
const installationId = $json.installation_id;

// This would call the backend to post a PR comment with summary
// For now, return the data needed
return [{
  json: {
    url: `http://backend:8000/api/v1/webhooks/github/post-pr-comment`,
    method: 'POST',
    body: {
      analysis_id: analysis,
      pr_number: prNumber,
      repo_full_name: repo,
      installation_id: installationId
    }
  }
}];
